head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDINS21500.xml";
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 증권상품에 대한 속성 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    var temp1 = $c.stf.getObjectValue(cmb_product);
    var temp2 = txb_category.getValue();
    var temp3 = $c.stf.getObjectValue(cmb_attr_div);
    var temp4 = $c.stf.getObjectValue(cmb_group);
    if (temp1 == '') {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "증권상품"));
        cmb_product.focus();
        return false;
    }
    if (temp4 == '') {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "그룹"));
        cmb_group.focus();
        return false;
    }
    var url = "";
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=CFI_CD_ADMIN_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.cficd.admin.attr" + "&{P}category=" + txb_category.getValue() + $c.stf.getObjectValue(cmb_group) + "&{P}std_cd_prod_tp_cd=" + $c.stf.getObjectValue(cmb_product) + "&{P}attr_div=" + $c.stf.getObjectValue(cmb_attr_div);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_process	
 * 설명       : 저장, 수정, 삭제 한다. screenProcsTpCd 02,03,04
 ***********************************************/
scwin.ins_process = function(screenProcsTpCd) {
    if (screenProcsTpCd == '02') {
        // 신규저장

        //txb_KEY, txb_STD_CD_PROD_TP_CD 셋팅
        $c.stf.setObjectValue(txb_STD_CD_PROD_TP_CD, $c.stf.getObjectValue(cmb_product));
        $c.stf.setObjectValue(txb_KEY, $c.stf.getObjectValue(txb_category) + $c.stf.getObjectValue(cmb_group) + $c.stf.getObjectValue(cmb_attr_div) + $c.stf.getObjectValue(txb_CD_VAL));
        trs_save.Action = "/EtcInfoAction.do?method=registerCfiCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    } else if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (!confirm(cmb_attr_div.getText() + ' 코드정보를 [수정] 하시겠습니까?')) {
            return;
        }
        trs_save.Action = "/EtcInfoAction.do?method=modifyCfiCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=03";
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    } else if (screenProcsTpCd == '04') {
        // 삭제

        if (dts_List.getTotalRow() == 1) {
            $c.win.alert("해당 속성의 마지막 코드이므로 [삭제] 할 수 없습니다.");
            return;
        }
        var rtn = confirm(cmb_attr_div.getText() + ' 코드정보를 [삭제] 하시겠습니까?');
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {

            //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            dts_ListDelete.insertRow();
            dts_ListDelete.setCellData(1, "KEY", dts_List.getCellData(dts_List.getRowPosition(), "KEY"));
            dts_ListDelete.setCellData(1, "STD_CD_PROD_TP_CD", dts_List.getCellData(dts_List.getRowPosition(), "STD_CD_PROD_TP_CD"));
            trs_save.Action = "/EtcInfoAction.do?method=removeCfiCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
            trs_save.KeyName = "toinb_dataid4";
            trs_save.KeyValue = "JSP(I:pInput=dts_ListDelete)";
            trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
            trs_save.Post();
        }
    }
};





/********************************************** 
 * 함수명   : fn_new
 * 설명       :  신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.fn_new = function() {
    if (dts_List.getTotalRow() == 0) {
        $c.win.alert('해당 CFI코드를 [조회] 한 후에 추가 할 수 있습니다.');
        return;
    }
    dts_List.insertRow();
    scwin.fn_showObj(false);
    fn_CtrlBtn_temp("insert");
};


/********************************************** 
 * 함수명   : fn_modify_attr	
 * 설명       : 속성정보 [수정] 한다. screenProcsTpCd 03
 ***********************************************/
scwin.fn_modify_attr = function() {
    if (!$c.cp.isModified(dts_List)) {
        $c.win.alert("변경된 데이터가 없습니다.");
        return;
    }
    if (!confirm(cmb_attr_div.getText() + ' 안내사항을 [수정] 하시겠습니까?')) {
        return;
    }
    trs_save.Action = "/EtcInfoAction.do?method=modifyCfiCdAttrInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=03";
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_save.Post();
};


//신규등록시 obj가리기
scwin.fn_showObj = function(div) {
    if (div) {
        $c.stf.showObj(panel_3, true);
        txb_CD_VAL.setReadOnly(true);
        txb_CD_VAL.style.backgroundColor = '#b9d4f7';
        $c.stf.showObj(label_6, true);
        $c.stf.showObj(txb_ADJ_DDTM, true);
        $c.stf.showObj(label_11, true);
        $c.stf.showObj(txb_ADJPRN_ID, true);
    } else {
        $c.stf.showObj(panel_3, false);
        txb_CD_VAL.setReadOnly(false);
        txb_CD_VAL.style.backgroundColor = '#ffffff';
        $c.stf.showObj(label_6, false);
        $c.stf.showObj(txb_ADJ_DDTM, false);
        $c.stf.showObj(label_11, false);
        $c.stf.showObj(txb_ADJPRN_ID, false);
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    fn_CtrlBtn_temp("no");
    scwin.fn_showObj(true);

    //showObj(panel_12, false);
    if (js_emp_no.substring(0, 4) != "sysm") {
        $c.stf.showObj(panel_12, false);
    }

    //cfi콤보셋팅
    ins_combo_set(dts_cfi_product, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "04151", "SEL"); //상품구분코드
    //ins_combo_set2(dts_cfi_product, vScrenID, SCREN_PROCS_TP_CD_01 ,"04151","SEL","03"); //상품구분코드//주권제외
    //ins_cfi_set(dts_cfi_category, vScrenID, SCREN_PROCS_TP_CD_01, "01", "D", "", "", "G");

};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
        $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리
        scwin.fn_showObj(true);
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.cmb_product_OnSelChange = function() {
    var temp1 = $c.stf.getObjectValue(cmb_product);
    if (temp1 == '01' || temp1 == '07' || temp1 == '09' || temp1 == '11' || temp1 == '12' || temp1 == '13') {
        $c.stf.setObjectValue(txb_category, 'D');
    } else if (temp1 == '02' || temp1 == '06') {
        $c.stf.setObjectValue(txb_category, ''); //주권과 집합투자증권 카테고리를 동시에 보여줘야하므로 공란처리

    } else if (temp1 == '03') {
        $c.stf.setObjectValue(txb_category, 'C');
    } else if (temp1 == '04' || temp1 == '05' || temp1 == '10') {
        $c.stf.setObjectValue(txb_category, 'R');
    } else if (temp1 == '15') {
        //선물
        $c.stf.setObjectValue(txb_category, 'F');
    } else if (temp1 == '16') {
        //옵션
        $c.stf.setObjectValue(txb_category, 'O');
    } else if (temp1 == '18') {
        //지표
        $c.stf.setObjectValue(txb_category, 'T');
    } else if (temp1 == '26') {
        //선물(전략/스프레드)
        $c.stf.setObjectValue(txb_category, 'K');
    } else {
        $c.stf.setObjectValue(txb_category, '');
    }
    dts_List.removeAll();
    var temp2 = txb_category.getValue();
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp1, temp2, "", "", "G");
};
scwin.cmb_group_OnSelChange = function() {
    var temp1 = $c.stf.getObjectValue(cmb_product);
    var temp2 = $c.stf.getObjectValue(cmb_group);
    if (temp1 == '02') {
        if (temp2 == 'B' || temp2 == 'E' || temp2 == 'I') {
            //B:부동산투자회사, E:ETF, I:선박투자회사 --해당분류는 집합투자증권 카테고리
            $c.stf.setObjectValue(txb_category, 'C');
        } else {
            $c.stf.setObjectValue(txb_category, 'E');
        }
    } else if (temp1 == '06') {
        if (temp2 == 'E') {
            //E:주권예탁증서
            $c.stf.setObjectValue(txb_category, 'E');
        } else if (temp2 == 'D') {
            //D:채권예탁증서
            $c.stf.setObjectValue(txb_category, 'D');
        } else if (temp2 == 'R') {
            //R:권리예탁증서
            $c.stf.setObjectValue(txb_category, 'R');
        }
    }
    scwin.ins_search();
};
scwin.cmb_attr_div_OnSelChange = function() {
    scwin.ins_search();
    label_attr.setValue(cmb_attr_div.getText() + " 안내사항");
};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert('CFI코드가 저장되었습니다.');
    scwin.ins_search();
};
scwin.grd_Grid_OnClick = function(row, colid) {
    scwin.fn_showObj(true);
    if (row == 0) return;
};
scwin.btn_delete_onclick = function() {
    scwin.ins_process("04");
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.btn_save_onclick = function() {
    scwin.ins_process("02");
};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.btn_modify_attr_onclick = function() {
    scwin.fn_modify_attr();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn_temp("update");
};
scwin.dts_cfi_product_OnLoadCompleted = function(rowcount) {
    for (var i = dts_cfi_product.getTotalRow(); i > 0; i--) {
        if (dts_cfi_product.getCellData(i, "VALUE") == "12" || dts_cfi_product.getCellData(i, "VALUE") == "22" || dts_cfi_product.getCellData(i, "VALUE") == "23" || dts_cfi_product.getCellData(i, "VALUE") == "24" || dts_cfi_product.getCellData(i, "VALUE") == "25" ||
            dts_cfi_product.getCellData(i, "VALUE") == "17" || dts_cfi_product.getCellData(i, "VALUE") == "19" || dts_cfi_product.getCellData(i, "VALUE") == "20" || dts_cfi_product.getCellData(i, "VALUE") == "21" || dts_cfi_product.getCellData(i, "VALUE") == "14") {
            // 12,22,23,24,25, 17,19,20,21,14 삭제
            $c.cp.removeRow(dts_cfi_product, i);
        }
    }
};
